	use alloc::vec::Vec;

	pub const OP_OPEN: u16 = 1;
	pub const OP_ENDPOINTS: u16 = 2;
	pub const OP_START: u16 = 3;
	pub const OP_STOP: u16 = 4;
	pub const OP_EVENTS: u16 = 5;
	pub const OP_SEND: u16 = 6;
	pub const OP_BLOCKS: u16 = 7;

	pub trait Service {
		fn open(&mut self, version: u32) -> Result<MidiOpen, Error>;
		fn endpoints(&mut self) -> Result<Vec<MidiDeviceEndpoint>, Error>;
		fn start(&mut self, endpoint: u32, receiver_generation: u64) -> Result<(), Error>;
		fn stop(&mut self, endpoint: u32, receiver_generation: u64) -> Result<(), Error>;
		fn events(&mut self) -> Vec<MidiDeviceEvent>;
		/// Put at most 64 USB-MIDI 1.0 event packets on a TRANSMIT endpoint, in order. ANSWERED WHEN THE TRANSPORT
		/// HAS TAKEN ALL OF THEM, so a caller that waits for the answer is paced by the device and nothing queues
		/// behind it; refused on a receive endpoint, for a cable the endpoint does not carry, and for a batch that
		/// is not a whole number of packets.
		fn send(&mut self, endpoint: u32, packets: Vec<u8>) -> Result<(), Error>;
		/// A `ump` endpoint's function blocks; none for a `midi1` endpoint.
		fn blocks(&mut self, endpoint: u32) -> Result<Vec<MidiDeviceBlock>, Error>;
	}

	pub fn dispatch<S: Service>(service: &mut S, request: &[u8], request_handles: &mut Handles, out: &mut [u8], reply_handles: &mut Handles) -> Option<usize> {
		let mut reader = Reader::with_handle_list(request, request_handles);
		let r = &mut reader;
		let op = r.u16()?;
		let corr = r.u32()?;
		let mut writer = SliceWriter::new(out);
		if op == PROTOCOL_INFO_OP {
			r.finish()?;
			request_handles.clear();
			let w = &mut writer;
			w.u32(corr)?;
			w.bytes_lp(b"liber:midi-device")?;
			w.u32(1)?;
			match Handles::try_from_slice(writer.handles()) {
				Some(taken) => *reply_handles = taken,
				None => return None,
			}
			return Some(writer.pos());
		}
		match op {
			OP_OPEN => {
				let version = r.u32()?;
				r.finish()?;
				request_handles.clear();
				let result = service.open(version);
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v7) => {
							w.u8(1)?;
							v7.write(w)?;
						}
						Err(v8) => {
							w.u8(0)?;
							v8.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			OP_ENDPOINTS => {
				r.finish()?;
				request_handles.clear();
				let result = service.endpoints();
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v9) => {
							w.u8(1)?;
							if v9.len() > u16::MAX as usize {
								return None;
							}
							w.u16(v9.len() as u16)?;
							for v11 in v9.iter() {
								v11.write(w)?;
							}
						}
						Err(v10) => {
							w.u8(0)?;
							v10.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			OP_START => {
				let endpoint = r.u32()?;
				let receiver_generation = r.u64()?;
				r.finish()?;
				request_handles.clear();
				let result = service.start(endpoint, receiver_generation);
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v12) => {
							w.u8(1)?;
						}
						Err(v13) => {
							w.u8(0)?;
							v13.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			OP_STOP => {
				let endpoint = r.u32()?;
				let receiver_generation = r.u64()?;
				r.finish()?;
				request_handles.clear();
				let result = service.stop(endpoint, receiver_generation);
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v14) => {
							w.u8(1)?;
						}
						Err(v15) => {
							w.u8(0)?;
							v15.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			OP_SEND => {
				let endpoint = r.u32()?;
				let packets = {
					let v16 = r.u16()? as usize;
					let v16 = (v16 <= 256).then_some(v16)?;
					let mut v17 = Vec::new();
					v17.try_reserve_exact(v16).ok()?;
					for _ in 0..v16 {
						v17.push(r.u8()?);
					}
					v17
				};
				r.finish()?;
				request_handles.clear();
				let result = service.send(endpoint, packets);
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v18) => {
							w.u8(1)?;
						}
						Err(v19) => {
							w.u8(0)?;
							v19.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			OP_BLOCKS => {
				let endpoint = r.u32()?;
				r.finish()?;
				request_handles.clear();
				let result = service.blocks(endpoint);
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v20) => {
							w.u8(1)?;
							if v20.len() > u16::MAX as usize {
								return None;
							}
							w.u16(v20.len() as u16)?;
							for v22 in v20.iter() {
								v22.write(w)?;
							}
						}
						Err(v21) => {
							w.u8(0)?;
							v21.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			_ => return None,
		}
		match Handles::try_from_slice(writer.handles()) {
			Some(taken) => *reply_handles = taken,
			None => return None,
		}
		Some(writer.pos())
	}

	pub fn events_open<S: Service>(service: &mut S, request: &[u8], request_handles: &mut Handles) -> Option<(u32, Vec<MidiDeviceEvent>)> {
		let mut reader = Reader::with_handle_list(request, request_handles);
		let r = &mut reader;
		let _op = r.u16()?;
		let corr = r.u32()?;
		r.finish()?;
		request_handles.clear();
		let items = service.events();
		Some((corr, items))
	}
	pub fn events_frame(seq: u32, item: &MidiDeviceEvent, out: &mut [u8], frame_handles: &mut Handles) -> Option<usize> {
		let mut writer = SliceWriter::new(out);
		let encoded: Option<()> = (|| {
			let w = &mut writer;
			w.u32(seq)?;
			item.write(w)?;
			Some(())
		})();
		if encoded.is_none() {
			if let Some(taken) = Handles::try_from_slice(writer.handles()) {
				*frame_handles = taken;
			}
			return None;
		}
		*frame_handles = Handles::try_from_slice(writer.handles())?;
		Some(writer.pos())
	}
	pub fn events_read(msg: &[u8], frame_handles: &mut Handles) -> Option<MidiDeviceEvent> {
		let mut reader = Reader::with_handles(msg, frame_handles);
		let r = &mut reader;
		let _seq = r.u32()?;
		let value = MidiDeviceEvent::read(r)?;
		reader.finish()?;
		frame_handles.clear();
		Some(value)
	}

	fn transport_outcome(error: TransportError) -> Error {
		match error {
			// The request never left this process, so nothing happened and trying
			// again is safe - which is what `again` says.
			TransportError::SendRefused | TransportError::NoRoute => Error::Again,
			// It went out and no answer came back. The server may have acted before
			// it died or before the deadline; nobody knows, and `commit-uncertain` is
			// the answer `base.error` grew so a caller is not forced to guess.
			// The reply could not be held, or arrived and broke the framing rules. In
			// both the server ANSWERED, so it acted; this end simply cannot read what
			// it said, which is the same position as never hearing back.
			TransportError::PeerClosed | TransportError::ReceiveFailed | TransportError::TimedOut | TransportError::NoMemory | TransportError::Malformed => Error::CommitUncertain,
		}
	}

	pub struct Client<T: Transport> {
		transport: T,
		corr: u32,
		deadline: u64,
		last_error: Option<TransportError>,
	}

	impl<T: Transport> Client<T> {
		pub fn new(transport: T) -> Client<T> {
			Client { transport, corr: 0, deadline: 0, last_error: None }
		}
		pub fn with_deadline(transport: T, deadline: u64) -> Client<T> {
			Client { transport, corr: 0, deadline, last_error: None }
		}
		pub fn set_deadline(&mut self, deadline: u64) {
			self.deadline = deadline;
		}
		pub fn last_error(&self) -> Option<TransportError> {
			self.last_error
		}
		pub fn into_transport(self) -> T {
			self.transport
		}
		fn next_corr(&mut self) -> u32 {
			let c = self.corr;
			self.corr = self.corr.wrapping_add(1);
			c
		}
		pub fn protocol_info(&mut self) -> Option<(String, u32)> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(PROTOCOL_INFO_OP)?;
			w.u32(corr)?;
			// No parameter, so no capability: `into_inner` says so rather than this
			// line assuming it.
			let request = writer.into_inner()?;
			let mut reply_handles = Handles::new();
			let reply = self
				.transport
				.call(&request, &[], &mut reply_handles, self.deadline)
				.map_err(|e| {
					self.last_error = Some(e);
					e
				})
				.ok()?;
			if !reply_handles.is_empty() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			let mut reader = Reader::new(&reply);
			let r = &mut reader;
			if r.u32()? != corr {
				return None;
			}
			let package = r.string_lp()?;
			let version = r.u32()?;
			r.finish()?;
			Some((package, version))
		}
		pub fn open(&mut self, version: &u32) -> Option<Result<MidiOpen, Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_OPEN)?;
			w.u32(corr)?;
			w.u32(*version)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? { Ok(MidiOpen::read(r)?) } else { Err(Error::read(r)?) };
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
		pub fn endpoints(&mut self) -> Option<Result<Vec<MidiDeviceEndpoint>, Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_ENDPOINTS)?;
			w.u32(corr)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? {
					Ok({
						let v23 = r.u16()? as usize;
						let v23 = (v23 <= 8).then_some(v23)?;
						let mut v24 = Vec::new();
						v24.try_reserve_exact(v23).ok()?;
						for _ in 0..v23 {
							v24.push(MidiDeviceEndpoint::read(r)?);
						}
						v24
					})
				} else {
					Err(Error::read(r)?)
				};
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
		pub fn start(&mut self, endpoint: &u32, receiver_generation: &u64) -> Option<Result<(), Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_START)?;
			w.u32(corr)?;
			w.u32(*endpoint)?;
			w.u64(*receiver_generation)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? { Ok(()) } else { Err(Error::read(r)?) };
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
		pub fn stop(&mut self, endpoint: &u32, receiver_generation: &u64) -> Option<Result<(), Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_STOP)?;
			w.u32(corr)?;
			w.u32(*endpoint)?;
			w.u64(*receiver_generation)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? { Ok(()) } else { Err(Error::read(r)?) };
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
		pub fn events(&mut self) -> Option<u64> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_EVENTS)?;
			w.u32(corr)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = self
				.transport
				.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline)
				.map_err(|e| {
					self.last_error = Some(e);
					e
				})
				.ok()?;
			let mut reader = Reader::new(&reply);
			let r = &mut reader;
			if r.u32()? != corr || r.finish().is_none() || reply_handles.len() != 1 {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			Some(reply_handles.first())
		}
		pub fn send(&mut self, endpoint: &u32, packets: &[u8]) -> Option<Result<(), Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_SEND)?;
			w.u32(corr)?;
			w.u32(*endpoint)?;
			if packets.len() > u16::MAX as usize {
				return None;
			}
			w.u16(packets.len() as u16)?;
			for v25 in packets.iter() {
				w.u8(*v25)?;
			}
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? { Ok(()) } else { Err(Error::read(r)?) };
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
		pub fn blocks(&mut self, endpoint: &u32) -> Option<Result<Vec<MidiDeviceBlock>, Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_BLOCKS)?;
			w.u32(corr)?;
			w.u32(*endpoint)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? {
					Ok({
						let v26 = r.u16()? as usize;
						let v26 = (v26 <= 8).then_some(v26)?;
						let mut v27 = Vec::new();
						v27.try_reserve_exact(v26).ok()?;
						for _ in 0..v26 {
							v27.push(MidiDeviceBlock::read(r)?);
						}
						v27
					})
				} else {
					Err(Error::read(r)?)
				};
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
	}

